section.literal_block:
import urllib3
http = urllib3.PoolManager() resp = http.request( "POST", "https://httpbin.org/post", fields={"hello": "world"} # Add custom form fields )
print(resp.data) # b"{
 "form": {
 "hello": "world"
 }, ... }

import urllib3
# Making the request (The request function returns HTTPResponse object) resp = urllib3.request("GET", "https://httpbin.org/ip")
print(resp.status) # 200 print(resp.data) # b"{
 "origin": "104.232.115.37"
}
" print(resp.headers) # HTTPHeaderDict({"Content-Length": "32", ...})

import urllib3
resp = urllib3.request("GET", "https://httpbin.org/ip")
print(resp.json()) # {"origin": "127.0.0.1"}

import orjson import urllib3
encoded_data = orjson.dumps({"attribute": "value"}) resp = urllib3.request(method="POST", url="http://httpbin.org/post", body=encoded_data)
print(orjson.loads(resp.data)["json"]) # {'attribute': 'value'}

import urllib3

resp = urllib3.request(
    "GET",
    "https://httpbin.org/headers",
    headers={
        "X-Something": "value"
    }
)

print(resp.json()["headers"])
# {"X-Something": "value", ...}

import urllib3

resp = urllib3.request(
    "GET",
    "https://httpbin.org/cookies",
    headers={
        "Cookie": "session=f3efe9db; id=30"
    }
)

print(resp.json())
# {"cookies": {"id": "30", "session": "f3efe9db"}}

import urllib3

resp = urllib3.request(
    "GET",
    "https://httpbin.org/get",
    fields={"arg": "value"}
)

print(resp.json()["args"])
# {"arg": "value"}

import urllib3

resp = urllib3.request(
    "POST",
    "https://httpbin.org/post",
    fields={"field": "value"}
)

print(resp.json()["form"])
# {"field": "value"}

import urllib3

resp = urllib3.request(
    "POST",
    "https://httpbin.org/post",
    json={"attribute": "value"},
    headers={"Content-Type": "application/json"}
)

print(resp.json())
# {'headers': {'Content-Type': 'application/json', ...},
#  'data': '{"attribute":"value"}', 'json': {'attribute': 'value'}, ...}

resp = urllib3.request(
    "POST",
    "https://httpbin.org/post",
    fields={
        "filefield": ("example.txt", file_data, "text/plain"),
    }
)

section.paragraph:
Unless otherwise specified urllib3 will try to load the default system certificate stores.
                The most reliable cross-platform method is to use the certifi
                package which provides Mozilla’s root certificate bundle:

section.literal_block:
import urllib3

try:
    urllib3.request("GET","https://nx.example.com", retries=False)

except urllib3.exceptions.NewConnectionError:
    print("Connection failed.")
# Connection failed.
